                    continue
                add = grid[x1][y1]
                if x1 != x2 or y1 != y2:
                    add += grid[x2][y2]
                dp_cur[x1][x2] = best + add
        dp_prev = dp_cur

    return dp_prev[N][N] if N > 0 else 0

