def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    def is_day_statement(stmt: str) -> bool:
        """Return True if the statement contains any day of the week."""
        for day in days_of_week:
            if day in stmt:
                return True
        return False

    def evaluate(stmt: str, speaker: str) -> bool:
        """Evaluate the truth value of a statement given the scenario."""
        # Normalize punctuation
        stmt = stmt.strip()
        # Handle "I am guilty." / "I am not guilty."
        if stmt == "I am guilty.":
            return scenario == speaker
        if stmt == "I am not guilty.":
            return scenario != speaker
        # Handle "X is guilty." / "X is not guilty."
        if " is guilty." in stmt:
            name = stmt.split(" is guilty.")[0]
            return scenario == name
        if " is not guilty." in stmt:
            name = stmt.split(" is not guilty.")[0]
            return scenario != name
        # If statement doesn't match known patterns, assume it's true
        return True

    for speaker, stmts in statements.items():
        for stmt in stmts:
            if is_day_statement(stmt):
                continue
            truth = evaluate(stmt, speaker)
            if speaker in liar_count:
                if truth:
                    return False
            else:
                if not truth:
                    return False
    return True

def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    """
    Solve a 0/1 knapsack problem where the weight is time and the value is herb value.
    """
    # DP array where dp[t] is the maximum value achievable with time limit t
    dp = [0] * (T + 1)
    for time, value in herbs:
        if time > T:
            continue
        # iterate backwards to avoid using an item more than once
        for t in range(T, time - 1, -1):
            new_val = dp[t - time] + value
            if new_val > dp[t]:
                dp[t] = new_val
    return dp[T]

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
        heights (List[int]): A list of student heights.

    Returns:
        int: The minimum number of students that need to leave.
    """
    n = len(heights)
    if n <= 1:
        return 0

    # Longest increasing subsequence ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Longest decreasing subsequence starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[j] < heights[i] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Find maximum bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        bitonic_len = lis[i] + lds[i] - 1
        if bitonic_len > max_bitonic:
            max_bitonic = bitonic_len

    return n - max_bitonic
